    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        self.known_particles = []
        self.excluded_positions = set()

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']

        next_guess = None

        # Update known_particles and excluded_positions based on previous guess
        if prev_guess is not None:
            if is_particle:
                self.known_particles.append(tuple(prev_guess))
            else:
                self.excluded_positions.add(tuple(prev_guess))

        # Check if all particles are found
        if len(self.known_particles) == num_particles:
            next_guess = [0] * dimension
        else:
            # Iterate through all possible vectors in lex order
            for num in range(0, 2**dimension):
                vec = []
                for i in range(dimension):
                    bit = (num >> (dimension - 1 - i)) & 1
                    vec.append(bit)
                vec_tuple = tuple(vec)

                # Check if excluded
                if vec_tuple in self.excluded_positions:
                    continue

                # Check distance constraints against known particles
                valid = True
                for p in self.known_particles:
                    hamming = sum(c1 != c2 for c1, c2 in zip(p, vec))
                    if hamming < distance:
                        valid = False
                        break
                if valid:
                    next_guess = vec
                    break

            # Fallback in case all are invalid (unlikely)
            if next_guess is None:
                for num in range(0, 2**dimension):
                    vec = []
                    for i in range(dimension):
                        bit = (num >> (dimension - 1 - i)) & 1
                        vec.append(bit)
                    vec_tuple = tuple(vec)
                    if vec_tuple not in self.excluded_positions:
                        next_guess = vec
                        break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

