        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        self.candidates = None
        self.known_particles = None
        self.num_found = 0

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']

        next_guess = None

        if prev_guess is None:
            # Initialize for the first move
            candidates = list(itertools.product([0, 1], repeat=dimension))
            self.candidates = [list(c) for c in candidates]
            self.known_particles = []
            self.num_found = 0
            next_guess = self.candidates[0]
        else:
            # Process previous result
            if is_particle:
                self.known_particles.append(prev_guess.copy())
                self.num_found += 1
                forbidden_distance = distance - 1
                p = prev_guess
                # Create new_candidates excluding those within forbidden distance
                new_candidates = []
                for c in self.candidates:
                    dist = sum(a != b for a, b in zip(c, p))
                    if dist > forbidden_distance:
                        new_candidates.append(c)
                self.candidates = new_candidates
            else:
                # Remove prev_guess from candidates
                new_candidates = []
                for c in self.candidates:
                    if c != prev_guess:
                        new_candidates.append(c)
                self.candidates = new_candidates

            # Choose next guess
            if self.num_found >= num_particles:
                if not self.candidates:
                    next_guess = [0] * dimension
                else:
                    next_guess = self.candidates[0]
            else:
                if not self.candidates:
                    next_guess = [0] * dimension
                else:
                    next_guess = self.candidates[0]

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

